  '<form clrForm clrLayout="horizontal" #form="ngForm" (ngSubmit)="submit(form)">\n  <cll-datagrid-selection\n    name="organizationId"\n    [(ngModel)]="organizationId"\n    required\n    [error]="\'organizationExample.required\' | translate"\n  >\n    <label class="clr-control-label">{{ \'organizationExample.organization\' | translate }}</label>\n    @if (organizationsQuery.error()) {\n      <cll-alert>\n        {{\n          (organizationsQuery.isRefreshError() ? \'organizationExample.refreshError\' : \'organizationExample.loadError\')\n            | translate\n        }}\n        <button type="button" class="btn btn-link" (click)="organizationsQuery.reload()">\n          {{ \'organizationExample.retry\' | translate }}\n        </button>\n      </cll-alert>\n    }\n    <clr-datagrid\n      clrDgSelectionType="single"\n      [clrDgLoading]="organizationsQuery.isLoading()"\n      [clrDgItemsIdentityFn]="organizationKey"\n    >\n      <clr-dg-column clrDgField="name">{{ \'organizationExample.name\' | translate }}</clr-dg-column>\n      <clr-dg-row\n        *clrDgItems="let item of organizationsQuery.value() ?? []"\n        [clrDgItem]="item"\n        [clrDgRowSelectionLabel]="\'organizationExample.selectRow\' | translate: item.name"\n      >\n        <clr-dg-cell>{{ item.name }}</clr-dg-cell>\n      </clr-dg-row>\n    </clr-datagrid>\n  </cll-datagrid-selection>\n  <button type="submit" class="btn btn-primary">{{ \'organizationExample.submit\' | translate }}</button>\n  <button type="button" class="btn btn-secondary" (click)="reset(form)">\n    {{ \'organizationExample.reset\' | translate }}\n  </button>\n</form>\n';
/** Displayed TypeScript source for the asyncSubmit example. */
export const asyncSubmitTs =
  "import {JsonPipe} from '@angular/common';\nimport {ChangeDetectionStrategy, Component, computed, inject, signal} from '@angular/core';\nimport {\n  AsyncValidatorFn,\n  FormControl,\n  FormGroup,\n  FormGroupDirective,\n  ReactiveFormsModule,\n  Validators,\n} from '@angular/forms';\nimport {ClarityModule} from '@clr/angular';\nimport {AlertComponent, DatagridSelectionComponent, TranslatePipe, TranslationService} from 'clr-lift';\nimport {queryResource, toSignalForm} from 'ngx-lift';\nimport {filter, firstValueFrom} from 'rxjs';\n\nimport {STATUS_KEYS, type Organization} from './organization-example.data';\nimport {OrganizationService} from './organization.service';\n\nconst INELIGIBLE_KEYS = new Set(['org-4']);\n\n// Stands in for a server-side eligibility check; the demo never contacts a policy service.\nconst eligibility: AsyncValidatorFn = (control) =>\n  new Promise((resolve) => {\n    setTimeout(() => {\n      const rejected = ((control.value ?? []) as string[]).filter((key) => INELIGIBLE_KEYS.has(key));\n      resolve(rejected.length ? {ineligible: rejected} : null);\n    }, 800);\n  });\n\n@Component({\n  selector: 'app-async-organization-grid',\n  imports: [AlertComponent, ClarityModule, ReactiveFormsModule, JsonPipe, TranslatePipe, DatagridSelectionComponent],\n  templateUrl: './async-submit.component.html',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n})\nexport class AsyncSubmitComponent {\n  private readonly translationService = inject(TranslationService);\n  private readonly organizationService = inject(OrganizationService);\n\n  readonly organizationsQuery = queryResource(() => this.organizationService.listQuery('scope-1'));\n\n  readonly form = new FormGroup({\n    organizationIds: new FormControl<string[]>([], {\n      nonNullable: true,\n      validators: [Validators.required],\n      asyncValidators: [eligibility],\n      updateOn: 'submit',\n    }),\n  });\n  readonly sf = toSignalForm(this.form);\n  readonly submitted = signal<readonly string[] | undefined>(undefined);\n  readonly selectionError = computed(() => {\n    const errors = this.sf.fields.organizationIds.errors();\n    if (!errors) return '';\n    if (errors['required']) return this.translationService.translate('organizationExample.required');\n    if (errors['ineligible']) return this.translationService.translate('selectionDemo.asyncError');\n    return this.translationService.translate('organizationExample.invalidSelection');\n  });\n  readonly statusKeys = STATUS_KEYS;\n  readonly organizationKey = (item: Organization) => item.id;\n\n  async submit(): Promise<void> {\n    this.submitted.set(undefined);\n    // updateOn: 'submit' starts the async validator during the form submission; wait for its verdict.\n    if (this.form.pending) {\n      await firstValueFrom(this.form.statusChanges.pipe(filter((status) => status !== 'PENDING')));\n    }\n    if (this.form.invalid) {\n      this.form.markAllAsTouched();\n      return;\n    }\n    const payload = this.sf.submitValue();\n    this.submitted.set(payload.organizationIds === undefined ? [] : [...payload.organizationIds]);\n  }\n\n  reset(formView: FormGroupDirective): void {\n    formView.resetForm({organizationIds: []});\n    this.submitted.set(undefined);\n  }\n}\n";
/** Displayed HTML source for the asyncSubmit example. */
export const asyncSubmitHtml =
  '<form #formView="ngForm" clrForm clrLayout="vertical" [formGroup]="form" (ngSubmit)="submit()">\n  <cll-datagrid-selection\n    formControlName="organizationIds"\n    required\n    [helper]="\'selectionDemo.asyncSubmitHelp\' | translate"\n    [error]="selectionError()"\n  >\n    <label class="clr-control-label">{{ \'organizationExample.organizations\' | translate }}</label>\n    @if (organizationsQuery.error()) {\n      <cll-alert>\n        {{\n          (organizationsQuery.isRefreshError() ? \'organizationExample.refreshError\' : \'organizationExample.loadError\')\n            | translate\n        }}\n        <button type="button" class="btn btn-link" (click)="organizationsQuery.reload()">\n          {{ \'organizationExample.retry\' | translate }}\n        </button>\n      </cll-alert>\n    }\n    <clr-datagrid\n      clrDgSelectionType="multi"\n      [clrDgLoading]="organizationsQuery.isLoading()"\n      [clrDgItemsIdentityFn]="organizationKey"\n    >\n      <clr-dg-column clrDgField="name">{{ \'organizationExample.name\' | translate }}</clr-dg-column>\n      <clr-dg-column clrDgField="status">{{ \'organizationExample.status\' | translate }}</clr-dg-column>\n      <clr-dg-row\n        *clrDgItems="let item of organizationsQuery.value() ?? []"\n        [clrDgItem]="item"\n        [clrDgRowSelectionLabel]="\'organizationExample.selectRow\' | translate: item.name"\n      >\n        <clr-dg-cell>{{ item.name }}</clr-dg-cell>\n        <clr-dg-cell>{{ statusKeys[item.status] | translate }}</clr-dg-cell>\n      </clr-dg-row>\n    </clr-datagrid>\n  </cll-datagrid-selection>\n  @if (sf.pending()) {\n    <p role="status">{{ \'selectionDemo.asyncChecking\' | translate }}</p>\n  }\n  <div cds-layout="horizontal gap:md wrap:wrap">\n    <button type="submit" class="btn btn-primary" [clrLoading]="sf.pending()">\n      {{ \'organizationExample.submit\' | translate }}\n    </button>\n    <button type="button" class="btn btn-secondary" (click)="reset(formView)">\n      {{ \'organizationExample.reset\' | translate }}\n    </button>\n  </div>\n</form>\n@if (submitted(); as submittedKeys) {\n  <p role="status">{{ \'selectionDemo.asyncSubmitted\' | translate }}: {{ submittedKeys.join(\', \') }}</p>\n}\n<pre tabindex="0">{{ sf.submitValue() | json }}</pre>\n';
/** Displayed TypeScript source for the server example. */
export const serverTs =
  "import {JsonPipe} from '@angular/common';\nimport {ChangeDetectionStrategy, Component, computed, effect, inject, OnDestroy, signal} from '@angular/core';\nimport {FormControl, FormGroup, FormGroupDirective, ReactiveFormsModule, Validators} from '@angular/forms';\nimport {ClarityModule, ClrDatagridSortOrder} from '@clr/angular';\nimport {AlertComponent, DatagridSelectionComponent, TranslatePipe, TranslationService} from 'clr-lift';\nimport {queryResource, toSignalForm} from 'ngx-lift';\nimport {Subscription} from 'rxjs';\n\nimport {STATUS_KEYS} from './organization-example.data';\nimport {\n  type ServerOrganization,\n  type ServerOrganizationScope,\n  type ServerOrganizationSort,\n  type ServerOrganizationStatus,\n} from './server-organization.data';\nimport {ServerOrganizationService} from './server-organization.service';\nimport {ServerNameFilter} from './server-name.filter';\n\n@Component({\n  selector: 'app-server-organization-grid',\n  imports: [AlertComponent, ClarityModule, JsonPipe, ReactiveFormsModule, TranslatePipe, DatagridSelectionComponent],\n  templateUrl: './server-page-form.component.html',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n})\n/** Direct server-paged form host: the page owns the query, eligibility validation and key-only submission. */\nexport class ServerPageFormComponent implements OnDestroy {\n  private readonly translationService = inject(TranslationService);\n  private readonly organizationService = inject(ServerOrganizationService);\n  private readonly nameFilterSubscription: Subscription;\n\n  /** Saved keys from the baseline include page rows that were never requested. */\n  readonly initialKeys = ['org-s-17', 'org-s-23'];\n  readonly savedKeys = ['org-s-05', 'org-s-11', 'org-s-15', 'org-s-23'];\n  readonly pageSize = 5;\n  readonly sortOrder = computed(() => (this.sort() === '-name' ? ClrDatagridSortOrder.DESC : ClrDatagridSortOrder.ASC));\n  readonly scope = signal<ServerOrganizationScope>('commerce');\n  readonly status = signal<ServerOrganizationStatus>('all');\n  readonly sort = signal<ServerOrganizationSort>('name');\n  readonly page = signal(1);\n  readonly readonly = signal(false);\n  readonly submitted = signal<readonly string[] | null>(null);\n  readonly nameFilter = new ServerNameFilter();\n  /** Only successfully loaded rows can supply a name or authoritative availability reason. Declared before the form so its validator can read it synchronously. */\n  private readonly known = signal<ReadonlyMap<string, ServerOrganization>>(new Map());\n  readonly form = new FormGroup({\n    organizationIds: new FormControl<string[]>([...this.initialKeys], {\n      nonNullable: true,\n      validators: [\n        Validators.required,\n        (control) => {\n          const unavailable = this.authoritativelyUnavailableKeys(control.value as readonly string[]);\n          return unavailable.length ? {unavailableOrganizations: unavailable} : null;\n        },\n      ],\n    }),\n  });\n  readonly sf = toSignalForm(this.form, {\n    includeDisabled: false,\n    // Angular keeps a disabled child in FormGroup.value, so a disabled control is excluded here.\n    omitIf: (_value, key) => this.form.get(key)?.disabled ?? false,\n  });\n  readonly organizationsQuery = queryResource(() =>\n    this.organizationService.listQuery({\n      scope: this.scope(),\n      name: this.nameFilter.query(),\n      status: this.status(),\n      sort: this.sort(),\n      page: this.page(),\n      pageSize: this.pageSize,\n    }),\n  );\n  readonly items = computed(() => this.organizationsQuery.value()?.items ?? []);\n  /** Keep the last settled total while the next page loads so server pagination does not clamp to page 1. */\n  private readonly settledTotal = signal(0);\n  readonly total = computed(() => this.organizationsQuery.value()?.total ?? this.settledTotal());\n  readonly lastPage = computed(() => Math.max(1, Math.ceil(this.total() / this.pageSize)));\n  readonly selected = computed(() => {\n    const known = this.known();\n    return this.sf.fields.organizationIds.value().map((key) => {\n      const item = known.get(key);\n      return {key, name: item?.name, unavailable: item?.status === 'maintenance'};\n    });\n  });\n  readonly selectionError = computed(() => {\n    const errors = this.sf.fields.organizationIds.errors();\n    if (!errors) return '';\n    if (errors['required']) return this.translationService.translate('organizationExample.required');\n    if (errors['unavailableOrganizations']) return this.translationService.translate('selectionDemo.unavailableError');\n    return this.translationService.translate('organizationExample.invalidSelection');\n  });\n  readonly statusKeys = STATUS_KEYS;\n  readonly organizationKey = (item: ServerOrganization) => item.id;\n  readonly nameComparator = {\n    compare: (a: ServerOrganization, b: ServerOrganization) => a.name.localeCompare(b.name, 'en'),\n  };\n  readonly availability = (item: ServerOrganization) => ({\n    disabled: item.status === 'maintenance',\n    disabledReason:\n      item.status === 'maintenance' ? this.translationService.translate('organizationExample.maintenance') : undefined,\n  });\n  readonly evidence = computed(() => {\n    const scope = this.translationService.translate(\n      this.scope() === 'commerce' ? 'selectionDemo.serverCommerce' : 'selectionDemo.serverPublic',\n    );\n    const sort = this.translationService.translate(\n      this.sort() === '-name' ? 'selectionDemo.serverSortDesc' : 'selectionDemo.serverSortAsc',\n    );\n    return this.translationService.translate(\n      'selectionDemo.serverEvidence',\n      this.page(),\n      this.lastPage(),\n      this.total(),\n      scope,\n      sort,\n    );\n  });\n\n  constructor() {\n    effect(() => {\n      const page = this.organizationsQuery.value();\n      if (!page) return;\n      this.settledTotal.set(page.total);\n      if (!page.items.length) return;\n      this.known.update((known) => {\n        const next = new Map(known);\n        for (const item of page.items) next.set(item.id, item);\n        return next;\n      });\n    });\n    this.sf.revalidate(this.form.controls.organizationIds, () => this.known());\n    this.nameFilterSubscription = this.nameFilter.changes.subscribe(() => this.page.set(1));\n  }\n\n  ngOnDestroy(): void {\n    this.nameFilterSubscription.unsubscribe();\n    this.nameFilter.destroy();\n  }\n\n  setScope(scope: ServerOrganizationScope): void {\n    this.scope.set(scope);\n    this.page.set(1);\n  }\n\n  setStatus(status: ServerOrganizationStatus): void {\n    this.status.set(status);\n    this.page.set(1);\n  }\n\n  setSort(order: ClrDatagridSortOrder): void {\n    this.sort.set(order === ClrDatagridSortOrder.DESC ? '-name' : 'name');\n    this.page.set(1);\n  }\n\n  setPage(page: number): void {\n    this.page.set(Math.max(1, page));\n  }\n\n  selectionLocked(): boolean {\n    return this.readonly() || this.form.controls.organizationIds.disabled || this.organizationsQuery.isLoading();\n  }\n\n  toggleDisabled(): void {\n    const control = this.form.controls.organizationIds;\n    if (control.disabled) control.enable();\n    else control.disable();\n  }\n\n  loadSaved(): void {\n    // Restore persisted keys even when their pages were never requested.\n    this.form.controls.organizationIds.setValue([...this.savedKeys]);\n    this.submitted.set(null);\n  }\n\n  removeSelection(key: string): void {\n    if (this.selectionLocked()) return;\n    const control = this.form.controls.organizationIds;\n    control.setValue(control.value.filter((selected) => selected !== key));\n    control.markAsDirty();\n    control.markAsTouched();\n  }\n\n  submit(): void {\n    if (this.sf.invalid() || this.sf.pending() || this.form.controls.organizationIds.disabled) {\n      this.form.markAllAsTouched();\n      return;\n    }\n    const payload = this.sf.submitValue();\n    // No wildcard: every selected key, including those from pages not currently loaded.\n    this.submitted.set(payload.organizationIds ? [...payload.organizationIds] : []);\n  }\n\n  reset(formView: FormGroupDirective): void {\n    formView.resetForm({organizationIds: [...this.initialKeys]});\n    this.submitted.set(null);\n  }\n\n  /**\n   * Lists saved keys the server authoritatively reports as unavailable.\n   * @param keys Selected keys, including keys whose pages were never requested.\n   * @returns Keys whose successfully loaded row is in maintenance; unloaded keys stay valid and unverified.\n   */\n  private authoritativelyUnavailableKeys(keys: readonly string[]): string[] {\n    const known = this.known();\n    return keys.filter((key) => known.get(key)?.status === 'maintenance');\n  }\n}\n";
/** Displayed HTML source for the server example. */
export const serverHtml =
  '<form #formView="ngForm" clrForm clrLayout="vertical" [formGroup]="form" (ngSubmit)="submit()">\n  <section cds-layout="vertical gap:md" [attr.aria-label]="\'selectionDemo.server\' | translate">\n    <div\n      class="selection-toolbar"\n      cds-layout="horizontal gap:md wrap:wrap"\n      role="group"\n      [attr.aria-label]="\'selectionDemo.serverControls\' | translate"\n    >\n      <clr-select-container>\n        <label for="server-scope">{{ \'selectionDemo.serverScope\' | translate }}</label>\n        <select clrSelect id="server-scope" [value]="scope()" (change)="setScope($any($event.target).value)">\n          <option value="commerce">{{ \'selectionDemo.serverCommerce\' | translate }}</option>\n          <option value="public">{{ \'selectionDemo.serverPublic\' | translate }}</option>\n        </select>\n      </clr-select-container>\n      <clr-select-container>\n        <label for="server-status">{{ \'organizationExample.status\' | translate }}</label>\n        <select clrSelect id="server-status" [value]="status()" (change)="setStatus($any($event.target).value)">\n          <option value="all">{{ \'organizationExample.allStatuses\' | translate }}</option>\n          <option value="ready">{{ \'organizationExample.ready\' | translate }}</option>\n          <option value="maintenance">{{ \'organizationExample.maintenance\' | translate }}</option>\n        </select>\n      </clr-select-container>\n      <span class="selection-toolbar-spacer"></span>\n      <label class="selection-toolbar-check">\n        <input type="checkbox" [checked]="readonly()" (change)="readonly.set(!readonly())" />\n        {{ \'selectionDemo.readonly\' | translate }}\n      </label>\n      <label class="selection-toolbar-check">\n        <input type="checkbox" [checked]="form.controls.organizationIds.disabled" (change)="toggleDisabled()" />\n        {{ \'selectionDemo.disabled\' | translate }}\n      </label>\n      <button type="button" class="btn btn-sm" (click)="organizationsQuery.reload()">\n        {{ \'common.refresh\' | translate }}\n      </button>\n      <button type="button" class="btn btn-sm" (click)="loadSaved()">\n        {{ \'selectionDemo.serverLoadSaved\' | translate }}\n      </button>\n    </div>\n    <section\n      data-testid="server-selection-summary"\n      [attr.aria-label]="\'selectionDemo.selectedTitle\' | translate"\n      cds-layout="vertical gap:xs"\n    >\n      <p role="status" aria-atomic="true">\n        {{ \'selectionDemo.serverSummary\' | translate: selected().length }}\n      </p>\n      <ul cds-layout="vertical gap:xs">\n        @for (selection of selected(); track selection.key) {\n          <li>\n            @if (selection.name) {\n              {{ selection.name }} ({{ selection.key }})\n            } @else {\n              {{ \'selectionDemo.serverOffPage\' | translate }} ({{ selection.key }})\n            }\n            @if (selection.unavailable) {\n              — {{ \'organizationExample.maintenance\' | translate }}\n            }\n            <button\n              type="button"\n              class="btn btn-link btn-sm"\n              [disabled]="selectionLocked()"\n              [attr.aria-label]="\'selectionDemo.removeKey\' | translate: selection.key"\n              (click)="removeSelection(selection.key)"\n            >\n              {{ \'selectionDemo.remove\' | translate }}\n            </button>\n          </li>\n        }\n      </ul>\n    </section>\n  </section>\n\n  <cll-datagrid-selection\n    formControlName="organizationIds"\n    required\n    [helper]="\'selectionDemo.serverHelp\' | translate"\n    [error]="selectionError()"\n    [readonly]="readonly()"\n    [itemAvailability]="availability"\n  >\n    <label class="clr-control-label">{{ \'organizationExample.organizations\' | translate }}</label>\n    @if (organizationsQuery.error()) {\n      <cll-alert data-testid="server-error">\n        {{\n          (organizationsQuery.isRefreshError() ? \'organizationExample.refreshError\' : \'organizationExample.loadError\')\n            | translate\n        }}\n        <button type="button" class="btn btn-link" (click)="organizationsQuery.reload()">\n          {{ \'organizationExample.retry\' | translate }}\n        </button>\n      </cll-alert>\n    }\n    <clr-datagrid\n      clrDgSelectionType="multi"\n      [clrDgLoading]="organizationsQuery.isLoading()"\n      [clrDgItemsIdentityFn]="organizationKey"\n    >\n      <clr-dg-column\n        [clrDgSortBy]="nameComparator"\n        [clrDgSortOrder]="sortOrder()"\n        [clrDgDisableUnsort]="true"\n        (clrDgSortOrderChange)="setSort($event)"\n      >\n        {{ \'organizationExample.name\' | translate }}\n        <clr-dg-filter [clrDgFilter]="nameFilter">\n          <clr-input-container>\n            <label class="clr-sr-only" for="server-name-filter">\n              {{ \'selectionDemo.serverNameFilter\' | translate }}\n            </label>\n            <input\n              clrInput\n              id="server-name-filter"\n              type="text"\n              [value]="nameFilter.query()"\n              (input)="nameFilter.set($any($event.target).value)"\n            />\n          </clr-input-container>\n        </clr-dg-filter>\n      </clr-dg-column>\n      <clr-dg-column>{{ \'organizationExample.status\' | translate }}</clr-dg-column>\n      @for (item of items(); track item.id) {\n        <clr-dg-row\n          [clrDgItem]="item"\n          [clrDgRowSelectionLabel]="\'organizationExample.selectRow\' | translate: item.name"\n        >\n          <clr-dg-cell>{{ item.name }}</clr-dg-cell>\n          <clr-dg-cell>\n            <span\n              class="label"\n              [class.label-success]="item.status === \'ready\'"\n              [class.label-warning]="item.status === \'maintenance\'"\n            >\n              {{ statusKeys[item.status] | translate }}\n            </span>\n          </clr-dg-cell>\n        </clr-dg-row>\n      }\n      <clr-dg-footer>\n        <clr-dg-pagination\n          [clrDgPageSize]="pageSize"\n          [clrDgPage]="page()"\n          [clrDgTotalItems]="total()"\n          (clrDgPageChange)="setPage($event)"\n        />\n      </clr-dg-footer>\n    </clr-datagrid>\n  </cll-datagrid-selection>\n\n  @if (organizationsQuery.isInitialLoading()) {\n    <p class="clr-sr-only" role="status">{{ \'selectionDemo.serverLoading\' | translate }}</p>\n  }\n  @if (!organizationsQuery.error() && organizationsQuery.value() && total() === 0) {\n    <p role="status" data-testid="server-empty">{{ \'selectionDemo.serverEmpty\' | translate }}</p>\n  }\n  @if (organizationsQuery.value()) {\n    <p data-testid="server-page-evidence">{{ evidence() }}</p>\n  }\n\n  <div cds-layout="horizontal gap:md wrap:wrap">\n    <button\n      type="submit"\n      class="btn btn-primary"\n      [disabled]="sf.invalid() || sf.pending() || form.controls.organizationIds.disabled"\n    >\n      {{ \'selectionDemo.serverSubmit\' | translate }}\n    </button>\n    <button type="button" class="btn btn-secondary" (click)="reset(formView)">\n      {{ \'organizationExample.reset\' | translate }}\n    </button>\n  </div>\n</form>\n@if (submitted() !== null) {\n  <p role="status" data-testid="server-submitted">\n    {{ \'selectionDemo.serverSubmitted\' | translate: submitted()?.join(\', \') }}\n  </p>\n}\n<pre data-testid="server-json" tabindex="0">{{ sf.submitValue() | json }}</pre>\n';
/** Displayed TypeScript source for the serverPicker example. */
export const serverPickerTs =
  "import {JsonPipe} from '@angular/common';\nimport {ChangeDetectionStrategy, Component, computed, inject, signal} from '@angular/core';\nimport {FormControl, FormGroup, FormGroupDirective, ReactiveFormsModule, Validators} from '@angular/forms';\nimport {ClarityModule} from '@clr/angular';\nimport {TranslatePipe, TranslationService} from 'clr-lift';\nimport {toSignalForm} from 'ngx-lift';\n\nimport {ServerOrganizationPickerComponent} from './server-organization-picker.component';\n\n@Component({\n  selector: 'app-server-picker-form',\n  imports: [ClarityModule, JsonPipe, ReactiveFormsModule, ServerOrganizationPickerComponent, TranslatePipe],\n  templateUrl: './server-picker-form.component.html',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n})\n/** Parent host for the reusable picker: owns values, required validation, the baseline and the submit DTO. */\nexport class ServerPickerFormComponent {\n  private readonly translationService = inject(TranslationService);\n\n  /** Parent-owned baseline: saved keys include rows that live on pages the picker has not requested. */\n  readonly initialKeys = ['org-s-13', 'org-s-25'];\n  readonly readonly = signal(false);\n  readonly form = new FormGroup({\n    organizationIds: new FormControl<string[]>([...this.initialKeys], {\n      nonNullable: true,\n      validators: [Validators.required],\n    }),\n  });\n  readonly sf = toSignalForm(this.form, {\n    includeDisabled: false,\n    // Angular keeps a disabled child in FormGroup.value, so a disabled control is excluded here.\n    omitIf: (_value, key) => this.form.get(key)?.disabled ?? false,\n  });\n  readonly submitted = signal<readonly string[] | null>(null);\n  readonly selectionError = computed(() => {\n    const errors = this.sf.fields.organizationIds.errors();\n    if (!errors) return '';\n    if (errors['required']) return this.translationService.translate('organizationExample.required');\n    return this.translationService.translate('organizationExample.invalidSelection');\n  });\n\n  toggleDisabled(): void {\n    const control = this.form.controls.organizationIds;\n    if (control.disabled) control.enable();\n    else control.disable();\n  }\n\n  submit(): void {\n    if (this.sf.invalid() || this.sf.pending() || this.form.controls.organizationIds.disabled) {\n      this.form.markAllAsTouched();\n      return;\n    }\n    const payload = this.sf.submitValue();\n    // Key-only DTO belongs to the parent; the picker never sees the serialized payload.\n    this.submitted.set(payload.organizationIds ? [...payload.organizationIds] : []);\n  }\n\n  reset(formView: FormGroupDirective): void {\n    formView.resetForm({organizationIds: [...this.initialKeys]});\n    this.submitted.set(null);\n  }\n}\n";
/** Displayed HTML source for the serverPicker example. */
export const serverPickerHtml =
  '<form #formView="ngForm" clrForm clrLayout="vertical" [formGroup]="form" (ngSubmit)="submit()">\n  <div\n    class="selection-toolbar"\n    cds-layout="horizontal gap:md wrap:wrap"\n    role="group"\n    [attr.aria-label]="\'selectionDemo.policyControls\' | translate"\n  >\n    <label class="selection-toolbar-check">\n      <input type="checkbox" [checked]="readonly()" (change)="readonly.set(!readonly())" />\n      {{ \'selectionDemo.readonly\' | translate }}\n    </label>\n    <label class="selection-toolbar-check">\n      <input type="checkbox" [checked]="form.controls.organizationIds.disabled" (change)="toggleDisabled()" />\n      {{ \'selectionDemo.disabled\' | translate }}\n    </label>\n  </div>\n  <app-server-organization-picker\n    [error]="selectionError()"\n    [readonly]="readonly()"\n    formControlName="organizationIds"\n    required\n  />\n  <div cds-layout="horizontal gap:md wrap:wrap">\n    <button\n      type="submit"\n      class="btn btn-primary"\n      [disabled]="sf.invalid() || sf.pending() || form.controls.organizationIds.disabled"\n    >\n      {{ \'selectionDemo.serverSubmit\' | translate }}\n    </button>\n    <button type="button" class="btn btn-secondary" (click)="reset(formView)">\n      {{ \'organizationExample.reset\' | translate }}\n    </button>\n  </div>\n</form>\n@if (submitted() !== null) {\n  <p role="status" data-testid="server-picker-submitted">\n    {{ \'selectionDemo.serverSubmitted\' | translate: submitted()?.join(\', \') }}\n  </p>\n}\n<pre data-testid="server-picker-json" tabindex="0">{{ sf.submitValue() | json }}</pre>\n';
